{
  "name": "bt_hci_reset_handler",
  "confidence": "medium",
  "docstring": "Handles Bluetooth HCI reset command completion, clears controller/reset state, emits the corresponding HCI event, and restores scan or RF configuration depending on link-layer state.",
  "subsystem": "bt",
  "var_renames": {
    "v4": "reset_ctx",
    "v5": "pending_event",
    "v6": "scan_restore",
    "v0": "ll_ctx",
    "v1": "ll_state",
    "v2": "rf_state"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "pending reset/HCI event flag in reset_ctx"
    },
    {
      "offset": 33,
      "meaning": "flag indicating scan restoration is active"
    },
    {
      "offset": 48,
      "meaning": "link-layer context flags; bit 0x40 selects alternate RF index lookup"
    },
    {
      "offset": 59,
      "meaning": "link-layer reset/state byte (2/3/other dispatch)"
    }
  ]
}
